function tests = testVision
%TESTVISION Synthetic tests for the tag -> base frame pipeline (src/vision).
%   Tag corners are generated by projecting a known layout through a known
%   camera, so every recovered position and yaw can be checked exactly.
%   Run:  addpath(genpath('src')); runtests('tests')
    tests = functiontests(localfunctions);
end

function setupOnce(testCase)
    root = fileparts(fileparts(mfilename("fullpath")));
    addpath(genpath(fullfile(root, "src")));
    testCase.TestData.layout = syntheticLayout(fullfile(root, "config", "layout.json"));
    testCase.TestData.pose = syntheticCamera();
end

% -------------------------------------------------------------------------
function testRecoversEveryTarget(testCase)
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    tags = renderTags(truth, testCase.TestData.pose, layout, "ccw");
    scene = solveScene(tags, layout, testCase.TestData.pose.K, "AB");

    tol = 1e-6;
    verifyLessThan(testCase, scene.pose.reprojRms_px, tol);
    verifyLessThan(testCase, norm(scene.pose.cameraCenter_mm - testCase.TestData.pose.cameraCenter_mm), 1e-4);
    verifyLessThan(testCase, scene.baseCheck.centerError_mm, tol);

    ink = truth([truth.id] == layout.inkPad.id);
    expectedInk_mm = applyTagOffset(ink.centerUV_mm, ink.yaw_deg, layout.inkPad.offsetTag_mm);
    verifyEqual(testCase, scene.inkPad.UVW_mm, [expectedInk_mm layout.inkPad.targetHeight_mm], AbsTol=tol);
    verifyEqual(testCase, scene.inkPad.yaw_deg, ink.yaw_deg, AbsTol=tol);

    paper = truth([truth.id] == layout.paper.id);
    verifyEqual(testCase, scene.paper.UVW_mm, [paper.centerUV_mm layout.paper.height_mm], AbsTol=tol);
    verifyEqual(testCase, scene.paper.yaw_deg, paper.yaw_deg, AbsTol=tol);

    arm = truth([truth.id] == layout.arm.id);
    verifyEqual(testCase, scene.arm.UVW_mm, [arm.centerUV_mm layout.arm.height_mm], AbsTol=tol);

    for s = scene.stamps
        h = layout.stampHolders([layout.stampHolders.letter] == s.letter);
        tagTruth = truth([truth.id] == h.tagId);
        expectedDisc_mm = applyTagOffset(tagTruth.centerUV_mm, tagTruth.yaw_deg, layout.stamp.tagToDisc_mm);
        verifyEqual(testCase, s.disc_UVW_mm, [expectedDisc_mm layout.stamp.discHeight_mm], AbsTol=tol);
        verifyEqual(testCase, s.rho_mm, hypot(expectedDisc_mm(1), expectedDisc_mm(2)), AbsTol=tol);
        verifyEqual(testCase, s.source, "tag");
        verifyLessThan(testCase, s.onshapeResidual_mm, tol);
    end
    verifyTrue(testCase, all([scene.tags.sideOk]));
    verifyEmpty(testCase, scene.warnings);
end

function testHolderReferencesAndOnshapeSource(testCase)
    layout = testCase.TestData.layout;
    layout.useHolderTagsAsReference = true;
    layout.holderSource = "onshape";
    truth = syntheticTruth(layout);
    tags = renderTags(truth, testCase.TestData.pose, layout, "ccw");
    scene = solveScene(tags, layout, testCase.TestData.pose.K, "AB");

    % Holder A is at the base tag height so it becomes a reference; B is raised.
    verifyEqual(testCase, scene.pose.refTagIds, [layout.baseTag.id layout.stampHolders(1).tagId]);
    verifyNumElements(testCase, scene.warnings, 1);
    verifyLessThan(testCase, scene.pose.reprojRms_px, 1e-6);
    verifyEqual(testCase, [scene.stamps.source], ["onshape" "onshape"]);
end

function testMoreReferencesReduceNoise(testCase)
    % With noisy corners, adding a far-away reference tag should shrink the
    % error at the far end of the plate (less extrapolation from one tag).
    layout = testCase.TestData.layout;
    layout.stampHolders(2).tagHeight_mm = 0;          % make B coplanar so it can be a reference
    truth = syntheticTruth(layout);
    rng(1);
    trials = 40;
    err = zeros(trials, 2);
    for k = 1:trials
        tags = renderTags(truth, testCase.TestData.pose, layout, "ccw", 0.5);
        for useRefs = [false true]
            layout.useHolderTagsAsReference = useRefs;
            scene = solveScene(tags, layout, testCase.TestData.pose.K, "");
            paperTruth = truth([truth.id] == layout.paper.id);
            err(k, useRefs + 1) = norm(scene.paper.UVW_mm(1:2) - paperTruth.centerUV_mm);
        end
    end
    verifyLessThan(testCase, mean(err(:, 2)), mean(err(:, 1)));
end

function testMirroredWindingIsCaught(testCase)
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    tags = renderTags(truth, testCase.TestData.pose, layout, "cw");    % layout says ccw
    verifyError(testCase, @() solveScene(tags, layout, testCase.TestData.pose.K, ""), ...
        "estimateTablePose:mirrored");
end

function testMissingInkPadTag(testCase)
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    truth([truth.id] == layout.inkPad.id) = [];
    tags = renderTags(truth, testCase.TestData.pose, layout, "ccw");
    verifyError(testCase, @() solveScene(tags, layout, testCase.TestData.pose.K, ""), "scene:tagNotSeen");
end

function testMissingLetter(testCase)
    layout = testCase.TestData.layout;
    tags = renderTags(syntheticTruth(layout), testCase.TestData.pose, layout, "ccw");
    verifyError(testCase, @() solveScene(tags, layout, testCase.TestData.pose.K, "ABZ"), ...
        "scene:missingStamps");
end

function testWrongHeightIsFlagged(testCase)
    layout = testCase.TestData.layout;
    tags = renderTags(syntheticTruth(layout), testCase.TestData.pose, layout, "ccw");
    layout.arm.height_mm = 0;                 % the arm tag is really at 80 mm
    scene = solveScene(tags, layout, testCase.TestData.pose.K, "");
    armLoc = scene.tags([scene.tags.id] == layout.arm.id);
    verifyFalse(testCase, armLoc.sideOk);
    verifyTrue(testCase, any(contains(scene.warnings, "arm")));
end

function testUnfilledLayoutValue(testCase)
    layout = testCase.TestData.layout;
    layout.baseTag.yaw_deg = NaN;
    tags = renderTags(syntheticTruth(testCase.TestData.layout), testCase.TestData.pose, ...
        testCase.TestData.layout, "ccw");
    verifyError(testCase, @() solveScene(tags, layout, testCase.TestData.pose.K, ""), "layout:missingValue");
end

function testTagTargetFromBaseTagOnly(testCase)
    % Reach test: only the base tag and one other tag in the photo.
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    truth = truth(ismember([truth.id], [layout.baseTag.id 99]));
    tags = renderTags(truth, testCase.TestData.pose, layout, "ccw");
    result = solveTagTarget(tags, layout, testCase.TestData.pose.K, 99, 0);

    target = truth([truth.id] == 99);
    verifyEqual(testCase, result.target.UVW_mm, [target.centerUV_mm 0], AbsTol=1e-6);
    verifyEqual(testCase, result.target.yaw_deg, target.yaw_deg, AbsTol=1e-6);
    verifyEqual(testCase, result.target.phi_deg, atan2d(target.centerUV_mm(2), target.centerUV_mm(1)), AbsTol=1e-6);
    verifyLessThan(testCase, result.baseCheck.centerError_mm, 1e-6);
    verifyTrue(testCase, result.target.sideOk);
    verifyEmpty(testCase, result.warnings);

    verifyError(testCase, @() solveTagTarget(tags, layout, testCase.TestData.pose.K, 42, 0), "scene:tagNotSeen");
    verifyError(testCase, @() solveTagTarget(tags, layout, testCase.TestData.pose.K, layout.baseTag.id, 0), ...
        "tagTarget:sameTag");

    % The annotated image accepts a scene without ink pad, paper or stamps.
    scene = struct("pose", result.pose, "tags", result.tags, "inkPad", [], "paper", [], ...
        "arm", [], "stamps", [], "goal", struct("UVW_mm", result.target.UVW_mm, "label", "target 99"));
    img = drawScene(zeros(800, 1000, 3, "uint8"), scene, []);
    verifySize(testCase, img, [800 1000 3]);
end

function testFindHomographyFourPointsExact(testCase)
    planeUV_mm = [0 0; 50 0; 50 50; 0 50];
    Htrue = [2 0.1 300; -0.05 1.9 200; 1e-4 2e-4 1];
    px = applyHomography(Htrue, planeUV_mm);
    [H, roundTripErr_mm] = findHomography(px, planeUV_mm);
    verifyEqual(testCase, H, Htrue, AbsTol=1e-9);
    verifyLessThan(testCase, max(roundTripErr_mm), 1e-9);
end

% -------------------------------------------------------------------------
function layout = syntheticLayout(layoutPath)
% The real layout.json with every unmeasured value filled with test values.
    layout = loadLayout(layoutPath);
    layout.tagSize_mm = 50;
    layout.tagCornerWinding = 'ccw';
    layout.baseTag = struct('id', 0, 'centerUV_mm', [0 -90], 'yaw_deg', 90, 'height_mm', 0);
    layout.inkPad = struct('id', 1, 'height_mm', 22, 'offsetTag_mm', [0 -55], 'targetHeight_mm', 18);
    layout.paper = struct('id', 2, 'height_mm', 4, 'offsetTag_mm', [0 0], 'targetHeight_mm', NaN);
    layout.arm = struct('id', 3, 'height_mm', 80, 'offsetTag_mm', [0 0]);
    layout.stamp = struct('tagToDisc_mm', [0 40], 'discHeight_mm', 35);
    layout.holderSource = 'tags';
    layout.useHolderTagsAsReference = false;
    layout.stampHolders = struct( ...
        'letter', {'A', 'B'}, 'tagId', {10, 11}, 'tagHeight_mm', {0, 12}, ...
        'onshapeCenterUV_mm', {[-110 170], [120 180]}, 'onshapeYaw_deg', {30, -35});
end

function truth = syntheticTruth(layout)
% Where each tag really is (centre, yaw, height), consistent with the layout.
    truth = struct('id', {}, 'centerUV_mm', {}, 'yaw_deg', {}, 'height_mm', {});
    add = @(t, id, c, y, h) [t, struct('id', id, 'centerUV_mm', c, 'yaw_deg', y, 'height_mm', h)];
    truth = add(truth, layout.baseTag.id, layout.baseTag.centerUV_mm, layout.baseTag.yaw_deg, layout.baseTag.height_mm);
    truth = add(truth, layout.inkPad.id, [-180 40], 25, layout.inkPad.height_mm);
    truth = add(truth, layout.paper.id, [170 30], -12, layout.paper.height_mm);
    truth = add(truth, layout.arm.id, [10 30], 100, layout.arm.height_mm);
    for h = layout.stampHolders
        truth = add(truth, h.tagId, h.onshapeCenterUV_mm, h.onshapeYaw_deg, h.tagHeight_mm);
    end
    truth = add(truth, 99, [0 250], 0, 0);                % a tag not in the layout
end

function pose = syntheticCamera()
% Overhead camera, tilted ~12 deg, 650 mm above the plate.
    K = [2262.8 0 2835.1; 0 2261.5 2147.4; 0 0 1];       % close to the real calibration
    lookDown = [1 0 0; 0 -1 0; 0 0 -1];                   % camera x = +U, y = -V, z = -W
    tilt = [1 0 0; 0 cosd(12) -sind(12); 0 sind(12) cosd(12)] * ...
           [cosd(5) 0 sind(5); 0 1 0; -sind(5) 0 cosd(5)];
    R = tilt * lookDown;
    cameraCenter_mm = [30 -60 650];
    pose.K = K;
    pose.R = R;
    pose.t = -R * cameraCenter_mm.';
    pose.cameraCenter_mm = cameraCenter_mm;
end

function tags = renderTags(truth, pose, layout, winding, noise_px)
% Fake detectTags output: project each tag's corners through the camera.
    if nargin < 5
        noise_px = 0;
    end
    tags = struct('id', {}, 'cornerUV_px', {}, 'cornerUndist_px', {}, 'centerUV_px', {});
    for k = 1:numel(truth)
        corners_mm = tagCornersWorld(truth(k).centerUV_mm, truth(k).yaw_deg, layout.tagSize_mm, ...
            truth(k).height_mm, winding);
        px = projectWorldToPixel(pose, corners_mm) + noise_px * randn(4, 2);
        tags(end+1) = struct('id', truth(k).id, 'cornerUV_px', px, 'cornerUndist_px', px, ...
            'centerUV_px', mean(px, 1)); %#ok<AGROW>
    end
end
